        name: `BELLES Songs & Stories Tour`,
        sort_time: "2026-11-06 19:30:00",
        end_time_formatted: "2026-11-06 23:59",
        detail: "BELLES, a.k.a. Kelli Belles, stands out as an artist unapologetically true to herself. Hailing from Omaha and now based in Nashville, BELLES brings Midwestern grit and authenticity to everything she does, balancing small-town roots with big-stage ambition.\nAfter a landmark year highlighted by her remarkable self-penned song \"Son of Jolene,\" featuring global music icon Dolly Parton, BELLES brings her striking voice —eﬀortlessly blending a dreamy, modern edge with the timeless soul of country music’s Dolly-Tammy-Loretta Golden Era — to the Mockingbird stage this fall.",
